import pdfplumber, re, json
import pandas as pd
from difflib import SequenceMatcher

vendors = pd.read_excel('/root/vendors.xlsx')
pos = pd.read_csv('/root/purchase_orders.csv')

# normalization function
stopwords = {'ltd','limited','inc','incorporated','corp','corporation','co','company','llc'}

def normalize(name):
    # lower, remove non-alnum/space
    cleaned = re.sub(r'[^a-z0-9 ]', ' ', name.lower())
    parts = [p for p in cleaned.split() if p and p not in stopwords]
    return ' '.join(parts)

vendors['norm'] = vendors['name'].apply(normalize)

# map normalized name to best vendor for exact matches

def match_vendor(name):
    norm = normalize(name)
    # exact match on normalized
    exact = vendors[vendors['norm'] == norm]
    if len(exact) > 0:
        return exact.iloc[0]
    # fuzzy matching
    best = None
    best_score = 0
    for _, row in vendors.iterrows():
        score = SequenceMatcher(None, norm, row['norm']).ratio()
        if score > best_score:
            best_score = score
            best = row
    if best_score >= 0.85:
        return best
    return None

po_map = {row['po_number']: row for _, row in pos.iterrows()}

fraud = []

with pdfplumber.open('/root/invoices.pdf') as pdf:
    for i, page in enumerate(pdf.pages, start=1):
        text = page.extract_text() or ''
        # extract fields
        vendor = re.search(r'From:\s*(.*)', text)
        vendor_name = vendor.group(1).strip() if vendor else None
        amt = re.search(r'Total \$([0-9,.]+)', text)
        amount = float(amt.group(1).replace(',', '')) if amt else None
        iban = re.search(r'Payment IBAN:\s*(\S+)', text)
        iban_val = iban.group(1).strip() if iban else None
        po = re.search(r'PO Number:\s*(\S+)', text)
        po_num = po.group(1).strip() if po else None

        reason = None
        vendor_row = match_vendor(vendor_name) if vendor_name else None
        if vendor_row is None:
            reason = 'Unknown Vendor'
        else:
            if iban_val != vendor_row['iban']:
                reason = 'IBAN Mismatch'
            else:
                if po_num not in po_map:
                    reason = 'Invalid PO'
                else:
                    po_row = po_map[po_num]
                    if abs(amount - float(po_row['amount'])) > 0.01:
                        reason = 'Amount Mismatch'
                    else:
                        if po_row['vendor_id'] != vendor_row['id']:
                            reason = 'Vendor Mismatch'
        if reason:
            fraud.append({
                'invoice_page_number': i,
                'vendor_name': vendor_name,
                'invoice_amount': round(amount, 2) if amount is not None else None,
                'iban': iban_val,
                'po_number': po_num if po_num in po_map or po_num is None else (po_num if po_num else None),
                'reason': reason
            })

# write report
with open('/root/fraud_report.json', 'w') as f:
    json.dump(fraud, f, indent=2)

print('Fraud count:', len(fraud))
print(json.dumps(fraud[:5], indent=2))
